import re
def ko(i):
    if i in KO: return KO[i]
    jp=CT[i]
    if jp in BASE: return BASE[jp]
    m=re.match(r'^(.*?)([A-CSR])$',jp)
    if m and m.group(1) in BASE: return BASE[m.group(1)]+' '+m.group(2)
    return None
if __name__=='__main__':
    miss=[(i,CT[i]) for i in CT if ko(i) is None]; print('missing',miss)
    for i in CT: print(i,CT[i],'=>',ko(i))
